static int save(const char *name,const void *p,unsigned long n){FILE *file=fopen(name,"wb");int ok;if(!file)return 0;ok=fwrite(p,1,n,file)==n;return fclose(file)==0&&ok;}
static void le32(unsigned char *p,unsigned long n){memcpy(p,&n,4);}
static int wave(void){unsigned char bytes[108];memset(bytes,0,sizeof(bytes));memcpy(bytes,"RIFF",4);le32(bytes+4,100);memcpy(bytes+8,"WAVEfmt ",8);le32(bytes+16,16);bytes[20]=bytes[22]=1;le32(bytes+24,8000);le32(bytes+28,16000);bytes[32]=2;bytes[34]=16;memcpy(bytes+36,"data",4);le32(bytes+40,64);return save("script-parse-fixture/sound/quiet.wav",bytes,108);}
int bh_script_parse_checkpoint(unsigned long *count){VMFixture v;Fixture *f=&v.response.base;BHScriptParse parser;BHScriptDefinition definition;BHSoundLoad sounds;BHScriptVMState state;BHScriptTimerState *timer;BHScriptWaitState *wait;BHScriptTimerPacket event;BHMathEnvironment env;LPDIRECTSOUND device=0;BHEntity *node,*e,*fired,*next;unsigned long i,opcode,n,used;char line[128];const char *script;
 checks=failed=0;CHECK(bh_math_environment_enter(&env),"PC53");CHECK(model_file(),"actual collision fixture");CHECK(vm_fixture(&v),"real source dependencies");memset(&parser,0,sizeof(parser));memset(&definition,0,sizeof(definition));memset(&sounds,0,sizeof(sounds));parser.vm=&v.vm;parser.sounds=&sounds;parser.script_prefix="script-parse-fixture/";parser.sound_prefix="script-parse-fixture/sound/";sounds.queue=&f->sound;strcpy(definition.name,"cube.bsp");definition.grid=10;
 _mkdir("script-parse-fixture");_mkdir("script-parse-fixture/sound");CHECK(wave(),"real silent WAVE source data");CHECK(DirectSoundCreate(0,&device,0)==DS_OK&&device&&IDirectSound_SetCooperativeLevel(device,GetDesktopWindow(),DSSCL_NORMAL)==DS_OK,"actual native sound buffer device without playback");f->sound.device=device;
 script="; template tree\ngrid 12\ndefine Amount 3\nalpha on\nrender off\ntimer2 Amount 1.9 2.9\n  location 2 30 4\n  timer 1 0 0\n    citypart 55\n  end\n  alpha off\nend\nwaitfor 1 77\n  broadcast 10 9\nend\nblockturn on\nsound quiet.wav 1 0.5 200 0\nunknown ignored\n";
 CHECK(save("script-parse-fixture/cube.TXT",script,(unsigned long)strlen(script)),"script text fixture");v.vm.script_loading=1;CHECK(bh_script_parse_file(&parser,&definition)&&parser.created==9&&parser.ignored==1&&parser.depth==0,"whole parser creates full nested source tree");CHECK(definition.flags==3&&definition.grid==12&&definition.used_mask==1&&definition.values[0]==3&&!strcmp(definition.names[0],"Amount"),"grid, first variable and root flags applied");node=definition.script;timer=bh_script_timer_state(&v.vm.lifetime->timers,node);CHECK(timer&&timer->remaining==3&&timer->low==1&&timer->high==2&&timer->variable_remaining==0&&timer->fired&&timer->next,"real timer2 template fields, float truncation and links");fired=timer->fired;CHECK(bh_script_vm_read(fired,&state)&&state.opcode==20&&state.args[0]==2,"timer fired child is actual VM");next=(BHEntity*)word(fired,0xec);timer=bh_script_timer_state(&v.vm.lifetime->timers,next);CHECK(timer&&timer->fired&&timer->next,"nested ordinary timer and later sibling");CHECK(bh_script_vm_read(timer->next,&state)&&state.opcode==0&&state.args[0]==0&&state.args[1]==1,"nested flag is dynamic opcode0");
 wait=bh_script_wait_state(&v.vm.lifetime->timers,(BHEntity*)word(node,0xec));CHECK(wait&&wait->remaining==1&&wait->expected==77&&wait->fired,"real wait template and fired branch");e=wait->next;CHECK(bh_script_vm_read(e,&state)&&state.opcode==16&&state.args[0]==1&&state.args[1]==8,"blockturn uses owner flags even at root");e=state.next;CHECK(bh_script_vm_read(e,&state)&&state.opcode==1&&state.args[1]==1&&state.args[2]==0&&sounds.loads==1,"whole sound builder loads native buffer and creates actual VM args");
 /* Activating the real parsed timer clones and schedules actual callbacks,
    then the source tick enters the recovered whole VM. */
 v.states[0].variables[0]=3;event.event=8;event.actor=v.host;node->query(node,&event);CHECK(v.vm.lifetime->timers.error==BH_TIMER_OK&&f->pool.active->step,"parsed template activates through real source timer");for(e=f->pool.active;e;e=e->next){timer=bh_script_timer_state(&v.vm.lifetime->timers,e);if(e->step&&timer&&timer->fired==fired&&timer->actor==v.host)break;}CHECK(e&&timer,"actual scheduled timer selected among real siblings");if(e){timer->countdown=0;e->step(e);}CHECK(v.waypoints[2].speed==30&&v.waypoints[2].delay==4,"actual timer-to-VM waypoint behavior");
 /* Every original command prefix is parsed into its reviewed opcode. */
 {const char *keywords[]={"killsounds","killtimers","spark","explode","move","rotate","steam","fountain","deadcar","sensor","train","powerup","trigger2","marker","trigger","broadcast","detach","launch","citypart","location","blocker","rollercoaster"};long opcodes[]={2,3,4,7,5,12,6,9,8,10,11,13,22,24,14,18,15,17,19,20,23,21};FILE *file=fopen("script-parse-fixture/all.TXT","wb");for(i=0;i<22;++i)fprintf(file,"%s 1 2 3 4 5\n",keywords[i]);fclose(file);strcpy(definition.name,"all.bsp");definition.script=0;CHECK(bh_script_parse_file(&parser,&definition)&&parser.created==22,"all original command branches produce real VM templates");for(e=definition.script,i=0;e&&i<22;e=state.next,++i){bh_script_vm_read(e,&state);CHECK(state.opcode==opcodes[i]&&state.args[4]==5&&!state.variable_sum,"opcode order and all five literal arguments");}CHECK(i==22&&!e,"exact source chain termination");}
 strcpy(definition.name,"cube.bsp");definition.script=0;script="define Speed 8\ntimer 1 0 0\nmove Speed 2 3 4 5\nend\n";CHECK(save("script-parse-fixture/cube.TXT",script,(unsigned long)strlen(script))&&bh_script_parse_file(&parser,&definition),"variable command fixture");timer=bh_script_timer_state(&v.vm.lifetime->timers,definition.script);CHECK(timer&&bh_script_vm_read(timer->fired,&state)&&state.args[0]==8&&state.selectors[0]==0&&state.variable_sum==1,"actual argument owner resolves symbolic selector");
 parser.depth=0;parser.definition=&definition;strcpy(line,"radarblue onLater");CHECK(bh_script_parse_flag(&parser,line,512)&&definition.flags&512,"original on prefix match");strcpy(line,"radarblue offLater");CHECK(bh_script_parse_flag(&parser,line,512)&&!(definition.flags&512),"original off prefix match");used=parser.created;strcpy(line,"sound missing.wav 0 1 100 0");CHECK(bh_script_parse_sound(&parser,line)&&parser.created==used,"actual missing sound leaves no fake template");strcpy(line,"sound quiet.wav bad");CHECK(!bh_script_parse_sound(&parser,line)&&parser.error,"unwritten original scan locals become bounded failure");
 strcpy(definition.name,"absent.bsp");definition.flags=999;CHECK(bh_script_parse_file(&parser,&definition)&&definition.flags==6&&!definition.used_mask,"missing sidecar still applies original defaults");
 vm_finish(&v);remove("script-parse-fixture/sound/quiet.wav");remove("script-parse-fixture/cube.TXT");remove("script-parse-fixture/all.TXT");_rmdir("script-parse-fixture/sound");_rmdir("script-parse-fixture");remove("actor-damage-fixture/HUN_LOD1.BSP");_rmdir("actor-damage-fixture");bh_math_environment_leave(&env);if(count)*count=checks;printf("{\"scenario\":\"script-parse\",\"checks\":%lu,\"failures\":%lu,\"original_code_required\":false}\n",checks,failed);return failed!=0;
}
